package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;
import java.util.Map;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public interface OwnerMapper {

    Map<String, String> CITY_REGIONS = Map.of(
        "Sydney", "NSW",
        "Melbourne", "VIC",
        "Brisbane", "QLD");

    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(toInitials(owner))")
    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(toLocality(owner))")
    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
    @Mapping(target = "bulkSignupWarning", expression = "java(Boolean.TRUE.equals(owner.getBulkSignupWarning()))")
    @Mapping(target = "sharesHousehold", ignore = true)
    OwnerDto toOwnerDto(Owner owner);

    /**
     * The region of the owner's city from {@link #CITY_REGIONS}, or 'UNKNOWN' when the city is not listed.
     */
    default String toLocality(Owner owner) {
        return owner.getCity() == null ? "UNKNOWN" : CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
    }

    /**
     * 'EMAIL' when the owner has an email address, otherwise 'PHONE'.
     */
    default String toContactPreference(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isBlank() ? "EMAIL" : "PHONE";
    }

    /** The highest membership level assigned on create; level 4 is reserved for tenure. */
    int MAX_CREATE_MEMBERSHIP_LEVEL = 3;

    /**
     * Starts at 1, adds 1 when an email is present and 1 when the owner has no namesakes, capped at
     * {@link #MAX_CREATE_MEMBERSHIP_LEVEL}.
     */
    default Integer toMembershipLevel(Owner owner) {
        int level = 1;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            level++;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            level++;
        }
        return Math.min(level, MAX_CREATE_MEMBERSHIP_LEVEL);
    }

    /**
     * Builds the membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
     * the registration date's year.
     */
    default String toMembershipNumber(Owner owner) {
        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
            return null;
        }
        return String.format("%s-M%02d", owner.getCustomerCode(),
            Math.floorMod(owner.getRegistrationDate().getYear(), 100));
    }

    default String toInitials(Owner owner) {
        return initial(owner.getFirstName()) + initial(owner.getLastName());
    }

    private static String initial(String name) {
        return name == null || name.isEmpty() ? "" : Character.toUpperCase(name.charAt(0)) + ".";
    }

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    @Mapping(target = "customerCode", ignore = true)
    @Mapping(target = "householdId", ignore = true)
    @Mapping(target = "namesakeCount", ignore = true)
    @Mapping(target = "householdSize", ignore = true)
    @Mapping(target = "bulkSignupWarning", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}
package org.springframework.samples.petclinic.rest.validation;

import java.util.Map;
import java.util.regex.Pattern;

/**
 * Normalizes and validates owner telephone numbers into E.164 form.
 */
public final class OwnerTelephone {

    public static final String DEFAULT_COUNTRY_CODE = "61";

    public static final int MIN_DIGITS = 8;

    public static final int MAX_DIGITS = 15;

    /** Matches a normalized E.164 number: '+', a non-zero leading digit, {@value #MIN_DIGITS}-{@value #MAX_DIGITS} digits in total. */
    public static final String E164_REGEXP = "^\\+[1-9][0-9]{7,14}$";

    private static final Pattern E164 = Pattern.compile(E164_REGEXP);

    /** Required national-number length (digits after the country code) for known country codes. */
    public static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY_CODE = Map.of(
        "61", 9,
        "1", 10);

    private static final Pattern SEPARATORS = Pattern.compile("[\\s\\-()\\[\\]]");

    private OwnerTelephone() {
    }

    /**
     * Converts a telephone number to E.164 form. Spaces, dashes and brackets are removed. A number
     * with a leading '+' keeps its country code; otherwise a single leading '0' is dropped and the
     * default country code '+{@value #DEFAULT_COUNTRY_CODE}' is prepended. For country codes listed in
     * {@link #NATIONAL_DIGITS_BY_COUNTRY_CODE} the national number must have exactly the required length.
     *
     * @param telephone the telephone number as supplied in the request
     * @return the E.164 telephone number, e.g. {@code +61412345678}
     * @throws InvalidTelephoneException if the number cannot form a valid E.164 number
     */
    public static String normalize(String telephone) {
        if (telephone == null) {
            throw new InvalidTelephoneException(null);
        }
        String compact = SEPARATORS.matcher(telephone).replaceAll("");
        String e164;
        if (compact.startsWith("+")) {
            e164 = compact;
        } else {
            String national = compact.startsWith("0") ? compact.substring(1) : compact;
            e164 = "+" + DEFAULT_COUNTRY_CODE + national;
        }
        if (!E164.matcher(e164).matches()) {
            throw new InvalidTelephoneException(telephone);
        }
        checkNationalLength(e164, telephone);
        return e164;
    }

    private static void checkNationalLength(String e164, String telephone) {
        String digits = e164.substring(1);
        for (Map.Entry<String, Integer> entry : NATIONAL_DIGITS_BY_COUNTRY_CODE.entrySet()) {
            String countryCode = entry.getKey();
            if (digits.startsWith(countryCode)) {
                int required = entry.getValue();
                if (digits.length() - countryCode.length() != required) {
                    throw new InvalidTelephoneException(telephone, "Telephone number with country code '+"
                        + countryCode + "' must have exactly " + required + " national digits");
                }
                return;
            }
        }
    }
}

