package org.springframework.samples.petclinic.acceptance;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;

import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

/** identity-key: Consolidate all duplicate detection into a single derived 'identityKey' = normalizedTeleph... */
class AcceptanceTest extends AcceptanceBase {

	@Test
	void coreRejectsIdentityCollision() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("telephone", a.get("telephone").asText());
		createOwner(b).andExpect(status().isConflict()); // same identityKey
	}

	@Test
	void returnsIdentityKey() throws Exception {
		ObjectNode a = ownerNode();
		a.put("telephone", "0412 000 111");
		a.put("email", "Mixed.Case@Example.TEST");
		JsonNode owner = fetchOwner(createOwnerOk(a));
		assertThat(owner.get("identityKey").asText()).isEqualTo("+61412000111|mixed.case@example.test|");
	}

	@Test
	void conflictReportsIdentityKey() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		String key = fetchOwner(createOwnerOk(a)).get("identityKey").asText();
		ObjectNode b = ownerNode();
		b.put("telephone", a.get("telephone").asText());
		b.put("email", a.get("email").asText().toUpperCase());
		createOwner(b).andExpect(status().isConflict()).andExpect(jsonPath("$.identityKey").value(key));
	}

	@Test
	void sameTelephoneDifferentEmailIsAllowed() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("telephone", a.get("telephone").asText());
		b.put("email", uniqueEmail());
		createOwnerOk(b);
	}

	@Test
	void sameEmailDifferentTelephoneIsAllowed() throws Exception {
		ObjectNode a = ownerNode();
		a.put("email", uniqueEmail());
		createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("email", a.get("email").asText());
		createOwnerOk(b);
	}

	@Test
	void sameLastNameAndAddressWithoutSharingIsAllowed() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("lastName", a.get("lastName").asText());
		b.put("address", a.get("address").asText());
		createOwnerOk(b);
	}

	@Test
	void householdMembersWithDifferentTelephonesAreAllowed() throws Exception {
		ObjectNode a = ownerNode();
		int firstId = createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("lastName", a.get("lastName").asText());
		b.put("address", a.get("address").asText());
		b.put("sharesHousehold", true);
		JsonNode second = fetchOwner(createOwnerOk(b));
		JsonNode first = fetchOwner(firstId);
		String householdId = first.get("householdId").asText();
		assertThat(second.get("householdId").asText()).isEqualTo(householdId);
		assertThat(second.get("identityKey").asText()).endsWith("|" + householdId);
		assertThat(second.get("identityKey").asText()).isNotEqualTo(first.get("identityKey").asText());
	}

	@Test
	void householdMemberWithSameFullKeyIsRejected() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
		ObjectNode b = ownerNode();
		b.put("lastName", a.get("lastName").asText());
		b.put("address", a.get("address").asText());
		b.put("sharesHousehold", true);
		createOwnerOk(b);
		ObjectNode c = ownerNode();
		c.put("lastName", a.get("lastName").asText());
		c.put("address", a.get("address").asText());
		c.put("telephone", b.get("telephone").asText());
		c.put("sharesHousehold", true);
		createOwner(c).andExpect(status().isConflict());
	}

	@Test
	void sameTelephoneInDifferentHouseholdIsAllowed() throws Exception {
		ObjectNode a = ownerNode();
		createOwnerOk(a);
		ObjectNode member = ownerNode();
		member.put("lastName", a.get("lastName").asText());
		member.put("address", a.get("address").asText());
		member.put("telephone", a.get("telephone").asText());
		member.put("sharesHousehold", true);
		createOwnerOk(member); // the new householdId makes the key differ from a's
	}
}
EOF
